/**
 * 0016 — saved configuration templates.
 *
 * A template belongs to the guild it was saved from. `modules` is the same
 * per-module settings snapshot the dashboard exports: an array of
 * `{ id, version, settings }`, validated by the module schemas at save and at
 * apply. It is not a second `settings` table and applying a template still
 * writes through `SettingsService`.
 *
 * The unique index is on `lower(name)` so two operators cannot create
 * "AI strict" and "ai strict" in the same guild. The id is a UUID generated by
 * Postgres; the in-memory adapter uses `crypto.randomUUID`.
 */
export const version = "0016_config_templates";

export const sql = /* sql */ `
CREATE TABLE IF NOT EXISTS config_templates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  guild_id text NOT NULL,
  name text NOT NULL,
  description text NOT NULL DEFAULT '',
  modules jsonb NOT NULL,
  created_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX IF NOT EXISTS config_templates_guild_name_idx
  ON config_templates (guild_id, lower(name));
CREATE INDEX IF NOT EXISTS config_templates_guild_updated_idx
  ON config_templates (guild_id, updated_at DESC);
`;
